<?php require_once __DIR__.'/functions.php';require_once __DIR__.'/app_init.php';require_login();$pdo=dogvive_db();$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT * FROM usuario WHERE id_usuario=? AND LOWER(Tipo_usuario)='entrenador'");$q->execute([$id]);$t=$q->fetch();if(!$t){start_app('Entrenador no encontrado','entrenadores');echo '<div class="card"><h2>No encontramos ese perfil</h2>'.btn('Volver a entrenadores',page_url('entrenadores'),'btn-secondary').'</div>';end_app();exit;}$r=$pdo->prepare('SELECT AVG(Calificacion) AS promedio,COUNT(*) AS total FROM resena re JOIN reserva b ON b.id_reserva=re.id_reserva WHERE b.id_entrenador=?');$r->execute([$id]);$rating=$r->fetch();$reviews=$pdo->prepare('SELECT re.Calificacion,re.Comentario,re.Fecha,u.Nombre FROM resena re JOIN reserva b ON b.id_reserva=re.id_reserva JOIN usuario u ON u.id_usuario=re.id_usuario WHERE b.id_entrenador=? ORDER BY re.Fecha DESC LIMIT 10');$reviews->execute([$id]);$reviews=$reviews->fetchAll();start_app('Perfil del entrenador','entrenadores');page_wrap_start('Perfil profesional'); ?>
<div class="detail-grid"><div><div class="card"><div class="avatar" style="width:90px;height:90px;font-size:32px">🎓</div><h2 style="margin-top:18px"><?= e(trim($t['Nombre'].' '.$t['Apellido'])) ?></h2><p class="muted"><?= e((string)($t['Especialidad']?:'Especialidad no indicada')) ?></p><span class="badge <?= ($t['Estado_verificacion']??'')==='Verificado'?'green':'' ?>"><?= e((string)($t['Estado_verificacion']??'Pendiente')) ?> de verificación</span><div class="rating">⭐ <?= $rating['promedio']?number_format((float)$rating['promedio'],1):'Sin calificaciones' ?> <span class="muted">(<?= (int)($rating['total']??0) ?> reseñas)</span></div><div class="info-list"><div><span>⏱ Experiencia</span><strong><?= (int)($t['Experiencia']??0) ?> años</strong></div><div><span>📍 Ciudad</span><strong><?= e((string)($t['Ciudad']??$t['Direccion']??'No indicada')) ?></strong></div></div></div><div style="display:flex;gap:10px;margin-top:15px"><?= btn('💬 Contactar',base_url().'/mensajes.php?conversacion='.$id,'btn-secondary full') ?><?= btn('📅 Solicitar sesión',base_url().'/solicitud-servicio.php?entrenador='.$id,'btn-primary full') ?></div></div><div class="card"><h2>Sobre el entrenador</h2><p class="muted" style="line-height:1.8"><?= e((string)($t['Especialidad']?:'Este entrenador todavía no ha agregado una descripción profesional.')) ?></p><h3 style="margin-top:28px">Reseñas de clientes</h3><?php if(!$reviews): ?><p class="muted">Aún no hay reseñas para este perfil.</p><?php else: foreach($reviews as $review): ?><div class="booking-item"><div class="grow"><strong><?= e((string)$review['Nombre']) ?> · <?= str_repeat('★',(int)$review['Calificacion']) ?></strong><p class="muted"><?= e((string)$review['Comentario']) ?></p><small><?= e((string)$review['Fecha']) ?></small></div></div><?php endforeach;endif; ?></div></div><?php page_wrap_end();end_app();
